const A = (()=>{
  const C = window.ACADEMY_CATALOG;
  const U = window.ACADEMY_UPLOADS || {announcements:[],courses:[],agents:[],workflows:[],guides:[]};
  const slugify = x => String(x||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
  const PATHS = [...C.paths.filter(p=>!(U.courses||[]).some(x=>x.id===p.id)), ...(U.courses||[])];
  const FEATURES = [...C.features.filter(f=>!(U.agents||[]).some(x=>x.id===f.id)), ...(U.agents||[])];
  const TOOLS = [...C.tools.filter(t=>!(U.workflows||[]).some(x=>x.id===t.id)), ...(U.workflows||[])];
  const GUIDES = Object.fromEntries((U.guides||[]).map(g=>[g.id,g]));
  const pathMap = Object.fromEntries(PATHS.map(p=>[p.id,p]));
  const featureMap = Object.fromEntries(FEATURES.map(f=>[f.id,f]));
  const featureSlugMap = Object.fromEntries(FEATURES.map(f=>[f.slug||slugify(f.title),f]));
  const toolMap = Object.fromEntries(TOOLS.map(t=>[t.id,t]));
  const toolSlugMap = Object.fromEntries(TOOLS.map(t=>[t.slug||slugify(t.title),t]));
  const toolTitleMap = Object.fromEntries(TOOLS.map(t=>[t.title,t]));
  const featureTitleMap = Object.fromEntries(FEATURES.map(f=>[f.title,f]));
  const KEY='v_academy_v31_state';
  const defaultState={profile:{name:'',email:'',role:'Business Development Manager',permission:'Learner'},view:'dashboard',activePath:'foundations',activeLesson:'start_day',activeFeature:'feature_gmail',activeTool:'daily-startup',activeGuide:'',activeAnnouncement:'',completed:{},confidence:{},pins:[],journey:[],announcements:{},seenContent:{bulletins:[],tools:[]},adminUnlocked:false};
  let s = load();
  function load(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');return {...defaultState,...saved,announcements:{...defaultState.announcements,...(saved.announcements||{})},seenContent:{...defaultState.seenContent,...(saved.seenContent||{})}}}catch(e){return {...defaultState}}}
  function save(){localStorage.setItem(KEY,JSON.stringify(s));}
  function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
  function enc(x){return encodeURIComponent(x)} function dec(x){return decodeURIComponent(x)}
  function allKeys(){return PATHS.flatMap(p=>Object.keys(p.lessons).map(id=>p.id+'__'+id));}
  function pctPath(pathId){const p=pathMap[pathId];const ids=Object.keys(p.lessons).map(id=>pathId+'__'+id);return ids.length?Math.round(ids.filter(k=>s.completed[k]).length/ids.length*100):0}
  function totalProgress(){const ids=allKeys();return ids.length?Math.round(ids.filter(k=>s.completed[k]).length/ids.length*100):0}
  function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.display='block';clearTimeout(t._tm);t._tm=setTimeout(()=>t.style.display='none',1800)}
  function log(event,data={}){if(!s.profile.email)return;const profile={email:s.profile.email,name:s.profile.name,role:s.profile.role,currentCourse:s.activePath,overallProgress:totalProgress()};AcademySync.post({profile,event,data});}
  function journey(type,name,course){s.journey.unshift({ts:new Date().toLocaleString('en-AU'),type,name,course:course||''});s.journey=s.journey.slice(0,100);save();}
  function modal(title,msg,icon='🎉'){document.getElementById('modal').className='modal';document.getElementById('modal').innerHTML=`<div class="modalCard"><div class="icon">${icon}</div><h2>${title}</h2><p>${msg}</p><button class="btn gold" onclick="A.closeModal()">Continue</button></div>`}
  function closeModal(){document.getElementById('modal').className='modal hidden'}
  function copy(txt){navigator.clipboard.writeText(txt);toast('Copied')}
  function routeForState(){
    if(s.view==='updates'||s.view==='requiredBulletin')return '/bulletin-board';
    if(s.view==='announcementDetail'&&s.activeAnnouncement)return `/bulletin-board/${encodeURIComponent(s.activeAnnouncement)}`;
    if(s.view==='learningPaths')return '/training';
    if(s.view==='course')return `/training/${encodeURIComponent(s.activePath)}/${encodeURIComponent(s.activeLesson)}`;
    if(s.view==='resources')return '/tools';
    if(s.view==='featureDetail'){const f=featureMap[s.activeFeature];if(!f)return '/tools';return `/${f.resourceType==='Agent'?'agent':'tool'}/${encodeURIComponent(f.slug||slugify(f.title))}`;}
    if(s.view==='toolDetail'){const t=toolMap[s.activeTool];return t?`/workflow/${encodeURIComponent(t.slug||slugify(t.title))}`:'/tools';}
    if(s.view==='guide'){const g=GUIDES[s.activeGuide];return g?`/guide/${encodeURIComponent(g.slug||g.id)}`:'/bulletin-board';}
    if(s.view==='progress')return '/progress';
    if(s.view==='settings'||s.view==='admin')return '/settings';
    return '/';
  }
  function syncRoute(){
    const route=routeForState();
    if(location.protocol==='file:'){
      const hash=route==='/'?'':('#'+route);
      if(location.hash!==hash)history.pushState({academy:true},'',location.pathname+hash);
      return;
    }
    if(location.pathname!==route)history.pushState({academy:true},'',route);
  }
  function isRequiredAnnouncement(a){return a.required===true||a.acknowledgement==='required'}
  function isAnnouncementSeen(a){const st=announcementStatus(a);return isRequiredAnnouncement(a)?Boolean(st.openedAt||st.acknowledgedAt):Boolean(st.seenAt)}
  function newBulletinIds(){return (U.announcements||[]).filter(a=>a.showAsNew!==false&&!isAnnouncementSeen(a)).map(a=>a.id).filter(Boolean);}
  function newToolIds(){return FEATURES.filter(f=>f.showAsNew===true).map(f=>f.id).filter(Boolean).filter(id=>!(s.seenContent.tools||[]).includes(id));}
  function markToolSeen(id){if(!id)return;s.seenContent.tools=[...new Set([...(s.seenContent.tools||[]),id])];}
  function newBadge(show){return show?'<span class=\"navNewBadge\" aria-label=\"New content\">NEW</span>':'';}
  function render(){const catalog=['dashboard','requiredBulletin','updates','announcementDetail','learningPaths','resources','featureDetail','toolDetail','progress','settings','admin','guide'].includes(s.view);document.getElementById('app').className='app '+(catalog?'catalogOnly':'');document.getElementById('app').innerHTML=left()+middle()+main();bind();syncRoute();}
  function left(){const adminVisible=(s.profile.permission==='Administrator'||s.profile.permission==='Trainer'||s.adminUnlocked);return `<aside class="left"><div class="brand"><img src="assets/vanilla-logo.png"><div><h1>${esc(ACADEMY_CONFIG.academyName)}</h1><p>${esc(ACADEMY_CONFIG.subtitle)}</p></div></div><button class="profile profileLink" type="button" data-view="settings" aria-label="Open profile settings"><strong>${esc(s.profile.name||'Set up profile')}</strong><span class="small">${esc(s.profile.role||'Required before syncing')}</span><div class="progressbar"><div class="progressfill" style="width:${totalProgress()}%"></div></div><span class="small">Overall progress ${totalProgress()}%</span><span class="profileHint">Edit profile →</span></button><button class="navBtn ${s.view==='dashboard'?'active':''}" data-view="dashboard">🏠 Dashboard</button><button class="navBtn ${['updates','guide','announcementDetail','requiredBulletin'].includes(s.view)?'active':''}" data-view="updates"><span>📢 Bulletin Board</span>${newBadge(newBulletinIds().length>0)}</button><button class="navBtn ${s.view==='learningPaths'||s.view==='course'?'active':''}" data-view="learningPaths">📚 Training</button><button class="navBtn ${['resources','featureDetail','toolDetail'].includes(s.view)?'active':''}" data-view="resources"><span>🧰 Tools & Workflows</span>${newBadge(newToolIds().length>0)}</button><button class="navBtn ${s.view==='progress'?'active':''}" data-view="progress">📈 Progress</button><button class="navBtn ${s.view==='settings'?'active':''}" data-view="settings">⚙ Settings</button><div class="pinList"><strong>📌 Pinned tools</strong><div id="pinList">${s.pins.map((p,i)=>`<div class="pin" draggable="true" data-pin-index="${i}"><span>${esc(p)}</span><button data-unpin="${esc(p)}">×</button></div>`).join('')||'<p class="small">No pinned tools yet.</p>'}</div></div><p class="small">Version ${esc(ACADEMY_CONFIG.version)}</p></aside>`}
  function middle(){if(s.view!=='course')return '<aside class="middle blank"></aside>';const p=pathMap[s.activePath];return `<aside class="middle" id="courseMenu"><div class="courseTitle">${p.icon} ${esc(p.title)}</div><div class="progressbar"><div class="progressfill" style="width:${pctPath(p.id)}%"></div></div><p class="small">${pctPath(p.id)}% complete</p>${p.modules.map(m=>`<div class="moduleHead">${esc(m.heading)}</div>${m.lessons.map(id=>{const l=p.lessons[id];const done=s.completed[p.id+'__'+id];return `<button class="lessonBtn ${id===s.activeLesson?'active':''} ${done?'done':''}" data-lesson="${id}"><span class="dot">${done?'✓':'○'}</span><span>${l.icon||'•'} ${esc(l.title)}<br><span class="small">${esc(l.time)}</span></span></button>`}).join('')}`).join('')}</aside>`}
  function main(){return `<main class="main ${s.view==='guide'?'guideMain':''} ${s.view==='requiredBulletin'?'requiredBulletinMain':''}">${({dashboard,requiredBulletin,updates,announcementDetail,learningPaths,course:lesson,resources,featureDetail,toolDetail,progress,settings,admin,guide}[s.view]||dashboard)()}</main>`}
  function announcementStatus(a){return s.announcements[a.id]||{}}
  function announcementAction(a,compact=false){const st=announcementStatus(a);if(isRequiredAnnouncement(a)&&a.destination&&a.destination.type==='guide'){const label=st.acknowledgedAt?'Read again':(a.linkText||'Read guide');return `<button class="btn ${st.acknowledgedAt?'secondary':'gold'}" data-open-announcement="${esc(a.id)}" data-open-guide="${esc(a.destination.id)}">${esc(label)}</button>`}const label=st.seenAt?'View again':(a.linkText||'View update');return `<button class="btn ${st.seenAt?'secondary':'gold'}" data-open-bulletin="${esc(a.id)}">${esc(label)}</button>`}
  function announcementCard(a,required=false){const st=announcementStatus(a);const req=isRequiredAnnouncement(a);const progress=Math.max(0,Math.min(100,Number(st.progress||0)));const reqStatus=st.acknowledgedAt?'Acknowledged':(progress>0?'In progress':(st.openedAt?'Opened':'Not started'));const normalSeen=Boolean(st.seenAt);const readClass=req?st.acknowledgedAt:normalSeen;return `<div class="announcementCard ${req&&required?'requiredAction':''} ${readClass?'isRead':''}"><div><div class="announcementMeta">${a.badge?`<span class="pill">${esc(a.badge)}</span>`:''}<span class="small">Published ${esc(a.published||'')}</span>${req?(st.acknowledgedAt?`<span class="readStatus">✓ Read ${esc(formatDateTime(st.acknowledgedAt))}</span>`:`<span class="unreadStatus">● ${esc(reqStatus)} · ${progress}%</span>`):(normalSeen?`<span class="readStatus">✓ Seen ${esc(formatDateTime(st.seenAt))}</span>`:'<span class="unreadStatus">● New</span>')}</div><h4>${esc(a.title)}</h4><p>${esc(a.summary||'')}</p>${req&&!st.acknowledgedAt?`<div class="bulletinProgress"><div class="progressbar"><div class="progressfill" style="width:${progress}%"></div></div><span class="small">Reading progress ${progress}%</span></div>`:''}${req&&required&&!st.acknowledgedAt?'<p class="actionNote">Please read and acknowledge this update. Your acknowledgement is recorded against your Academy profile.</p>':''}</div>${announcementAction(a)}</div>`}
  function requiredAnnouncements(){return (U.announcements||[]).slice().sort((a,b)=>(b.priority||0)-(a.priority||0)).filter(a=>!announcementStatus(a).acknowledgedAt&&isRequiredAnnouncement(a))}
  function requiredBulletin(){const required=requiredAnnouncements();if(!required.length){s.view='dashboard';save();return dashboard()}const a=required[0];return `<section class="panel requiredFocus"><div class="eyebrow">Required reading</div><h2>${esc(a.title)}</h2><div class="requiredFocusMeta"><span class="pill">${esc(a.badge||'Required')}</span><span class="small">Published ${esc(a.published||'')}</span><span class="unreadStatus">● Not yet acknowledged</span></div><p class="requiredFocusSummary">${esc(a.summary||'')}</p><p class="actionNote">Please open this guide, read it and acknowledge it. Your acknowledgement will be recorded against your Academy profile.</p><div class="requiredFocusActions">${announcementAction(a)}<button class="btn secondary" data-view="updates">View Bulletin Board</button></div></section>${required.length>1?`<section class="panel"><h3>${required.length-1} more required item${required.length-1===1?'':'s'}</h3><p>Complete this item first. The next required notice will appear automatically.</p></section>`:''}`}
  function dashboard(){const n=nextLesson(), p=pathMap[n.path], l=p.lessons[n.lesson];const list=(U.announcements||[]).slice().sort((a,b)=>(b.priority||0)-(a.priority||0));const recent=list.slice(0,3);return `<section class="panel hero"><div class="eyebrow">Dashboard</div><h2>Welcome back, ${esc(s.profile.name||'there')}</h2><p>Recommended next step based on your progress.</p><div class="pathCard"><div><h4>${p.icon} ${esc(p.title)}</h4><p><b>Next workflow:</b> ${esc(l.title)}</p><p>${esc(l.why)}</p><span class="pill">${esc(l.time)}</span></div><button class="btn gold" data-open-path="${p.id}" data-open-lesson="${l.id}">${s.completed[p.id+'__'+l.id]?'Review':'Start / Continue'}</button></div></section>${recent.length?`<section class="panel"><div class="sectionHeading"><h3>Latest from the Bulletin Board</h3><button class="textBtn" data-view="updates">Open Bulletin Board →</button></div><div class="announcementList">${recent.map(a=>announcementCard(a)).join('')}</div></section>`:''}<section class="panel"><h3>Pinned tools</h3>${s.pins.length?`<div class="grid">${s.pins.map(p=>`<div class="card"><h4>📌 ${esc(p)}</h4><button class="btn secondary" data-tool="${esc(p)}">Open</button></div>`).join('')}</div>`:'<p>No pinned tools yet. Pin useful tools and workflows from Tools & Workflows.</p>'}</section><section class="panel vorsiPanel"><div class="eyebrow">Why VORSI exists</div><h3>Practical AI that improves how Vanilla works</h3><p><strong>VORSI is our internal approach to using AI with purpose.</strong> It brings together useful tools, reliable workflows, staff learning and responsible oversight so AI supports better work rather than becoming another disconnected system.</p><div class="grid2"><div class="card"><h4>What it stands for in practice</h4><ul><li>Use AI to strengthen judgement, not replace it.</li><li>Turn good individual ideas into repeatable team workflows.</li><li>Keep privacy, evidence and human review built into the process.</li></ul></div><div class="card"><h4>What it is for</h4><ul><li>Helping staff complete work more confidently and efficiently.</li><li>Keeping useful prompts, training and updates in one place.</li><li>Building capability that stays with Vanilla and improves over time.</li></ul></div></div></section><section class="panel"><h3>What changed in V3.10.4</h3><div class="list"><div class="tick">Newly released tools and Agents now show the same NEW badge on their actual card as well as in the sidebar.</div><div class="tick">The card badge and sidebar badge share the same seen state, so both disappear once the new item is opened.</div><div class="tick">Bulletin Board items continue to use content-specific New → Seen or required-reading behaviour.</div></div></section>`}
  function updates(){const list=(U.announcements||[]).slice().sort((a,b)=>(b.priority||0)-(a.priority||0));const unread=list.filter(a=>isRequiredAnnouncement(a)?!announcementStatus(a).acknowledgedAt:!announcementStatus(a).seenAt);const read=list.filter(a=>isRequiredAnnouncement(a)?Boolean(announcementStatus(a).acknowledgedAt):Boolean(announcementStatus(a).seenAt));return `<section class="panel hero"><div class="eyebrow">Bulletin Board</div><h2>Notices, required reading and new releases</h2><p>Published items stay here as a permanent record. Normal announcements become <strong>Seen</strong> when you open the update. Required reading is only complete after you acknowledge it.</p></section>${unread.length?`<section class="panel"><h3>New and unread</h3><div class="announcementList">${unread.map(a=>announcementCard(a,true)).join('')}</div></section>`:''}<section class="panel"><h3>${unread.length?'Seen and acknowledged':'All notices'}</h3>${read.length?`<div class="announcementList">${read.map(a=>announcementCard(a)).join('')}</div>`:'<p>No seen or acknowledged notices yet.</p>'}</section>`}
  function announcementDetail(){const a=(U.announcements||[]).find(x=>x.id===s.activeAnnouncement);if(!a)return `<section class="panel"><h2>Bulletin unavailable</h2><p>This bulletin could not be found.</p><button class="btn secondary" data-view="updates">Back to Bulletin Board</button></section>`;const st=announcementStatus(a);const sections=(a.sections||[]).map(sec=>`<section class="bulletinSection ${sec.tone?`bulletinTone-${esc(sec.tone)}`:''}">${sec.eyebrow?`<div class="eyebrow">${esc(sec.eyebrow)}</div>`:''}<h3>${esc(sec.title||'')}</h3>${sec.text?`<p>${esc(sec.text)}</p>`:''}${Array.isArray(sec.points)&&sec.points.length?`<ul>${sec.points.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}</section>`).join('');const actions=(a.actions||[]).map(x=>`<a class="btn ${x.style==='secondary'?'secondary':'gold'}" href="${esc(x.href||'#')}">${esc(x.label||'Open')}</a>`).join('');return `<section class="panel bulletinDetailHero"><div class="eyebrow">${esc(a.badge||'Bulletin Board')}</div><h2>${esc(a.title)}</h2><div class="announcementMeta"><span class="small">Published ${esc(a.published||'')}</span><span class="readStatus">✓ Seen ${esc(formatDateTime(st.seenAt||new Date().toISOString()))}</span></div><p class="bulletinLead">${esc(a.summary||'')}</p></section>${sections||`<section class="panel"><p>${esc(a.summary||'')}</p></section>`}<section class="panel bulletinDetailActions"><button class="btn secondary" data-view="updates">← Back to Bulletin Board</button>${actions}</section>`}
  function formatDateTime(value){try{return new Date(value).toLocaleString('en-AU',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'})}catch(e){return value||''}}
  function guide(){const g=GUIDES[s.activeGuide];if(!g)return `<section class="panel"><h2>Guide unavailable</h2><p>This guide could not be found.</p><button class="btn secondary" data-view="updates">Back to Bulletin Board</button></section>`;const a=(U.announcements||[]).find(x=>x.destination&&x.destination.type==='guide'&&x.destination.id===g.id);const st=a?announcementStatus(a):{};const progress=Math.max(0,Math.min(100,Number(st.progress||0)));const ack=a?(st.acknowledgedAt?`<span class="guideReadBadge">✓ Acknowledged ${esc(formatDateTime(st.acknowledgedAt))}</span>`:(s.profile.email?`<button class="btn green" data-ack-announcement="${esc(a.id)}">I have read this</button>`:`<button class="btn gold" data-view="settings">Set up profile to acknowledge</button>`)):'';return `<div class="guideToolbar"><button class="btn secondary" data-view="updates">← Back to Bulletin Board</button><div class="guideTitleBlock"><strong>${esc(g.title)}</strong><span class="small">Last reviewed ${esc(g.reviewed)} · ${esc(g.interfaceVersion)}</span>${a&&!st.acknowledgedAt?`<div class="guideProgressLine"><div class="progressbar"><div class="progressfill" style="width:${progress}%"></div></div><span class="small">${progress}% read</span></div>`:''}</div><div class="guideActions">${ack}<a class="btn secondary" href="${esc(g.src)}" target="_blank" rel="noopener">Open in new tab</a></div></div><iframe id="guideFrame" class="guideFrame" data-guide-id="${esc(g.id)}" data-announcement-id="${a?esc(a.id):''}" src="${esc(g.embedSrc||g.src)}" title="${esc(g.title)}"></iframe>`}
  function nextLesson(){for(const p of PATHS){for(const id of Object.keys(p.lessons)){if(!s.completed[p.id+'__'+id])return {path:p.id,lesson:id}}}return {path:'foundations',lesson:Object.keys(pathMap.foundations.lessons)[0]}}
  function learningPaths(){const group = g => PATHS.filter(p=>p.category===g).map(p=>`<div class="pathCard"><div><h4>${p.icon} ${esc(p.title)}</h4><p>${esc(p.description)}</p><span class="pill">${pctPath(p.id)}% complete</span><span class="pill">${esc((p.recommendedFor||[]).join(', '))}</span></div><button class="btn gold" data-open-path="${p.id}">${pctPath(p.id)===100?'Review':'Open'}</button></div>`).join('');return `<section class="panel hero"><div class="eyebrow">Training</div><h2>Choose what to learn next</h2><p>Complete core training or choose role-specific training. Tools & Workflows remains the single library for guidance and ready-to-use workflows.</p></section><section class="panel"><h3>Core Learning</h3>${group('Core Learning')}</section><section class="panel"><h3>Role Learning</h3>${group('Role Learning')}</section>`}
  function lesson(){const p=pathMap[s.activePath], l=p.lessons[s.activeLesson], key=p.id+'__'+l.id;return `<div class="breadcrumb"><button class="btn secondary" data-view="learningPaths">Training</button> › ${esc(p.title)} › ${esc(l.title)}</div><section class="panel hero"><div class="eyebrow">${esc(p.title)}</div><h2>${l.icon||''} ${esc(l.title)}</h2><div class="tools"><span class="pill">Suggested time: ${esc(l.time)}</span>${(l.tools||[]).map(t=>`<span class="toolChip">${esc(t)}</span>`).join('')}<button class="btn secondary" data-pin-tool="${esc(l.title)}">📌 Pin playbook</button></div></section>${lessonBody(l)}<section class="panel"><h3>Complete this workflow</h3><p class="small">This is your own progress record, not a test. Complete it only after genuinely trying the practical mission or walking through it with a realistic example.</p><div class="confidence"><button class="btn secondary" data-confidence="Confident">😊 Confident</button><button class="btn secondary" data-confidence="Getting there">🙂 Getting there</button><button class="btn secondary" data-confidence="Need practice">😐 Need practice</button></div><div class="completeRow"><span class="status ${s.completed[key]?'done':''}">${s.completed[key]?'Complete':'Not complete yet'}</span><button class="btn ${s.completed[key]?'secondary':'green'}" data-complete="${key}">${s.completed[key]?'Mark incomplete':'Complete mission'}</button></div></section>`}
  function lessonBody(l){return `<section class="panel"><h3>Why this matters</h3><p>${esc(l.why)}</p><div class="grid2"><div class="card"><h4>Use this when</h4><ul>${(l.when||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h4>Be careful when</h4><ul>${(l.avoid||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></section><section class="panel"><h3>Prompt pack</h3>${(l.prompts||[]).map(p=>promptCard(p.title,p.text)).join('')}</section><section class="panel"><h3>Mission</h3><div class="callout"><b>Do this with a real or realistic work example</b><ol>${(l.mission||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></section>`}
  function promptCard(title,text){return `<div class="promptCard"><div class="promptHead"><span>${esc(title)}</span><button class="btn secondary" data-copy="${enc(text)}">Copy prompt</button></div><div class="promptBody"><p class="small promptHint">Replace the bracketed details, then adapt the wording to the real task.</p><div class="prompt">${esc(text)}</div></div></div>`}
  function resources(){return `<section class="panel hero"><div class="eyebrow">Tools & Workflows</div><h2>One place to find the right AI help</h2><p>Browse feature guidance and ready-to-use Vanilla workflows together. Open an item to understand what it does before copying or pinning anything.</p></section><section class="panel"><h3>AI tools and capabilities</h3><p class="sectionIntro">Learn what each capability is for, where it helps, and what to watch out for.</p><div class="grid">${FEATURES.map(f=>{const isNew=f.showAsNew===true&&!(s.seenContent.tools||[]).includes(f.id);return `<div class="card resourceCard"><div class="resourceCardMeta"><div class="resourceType">${esc(f.resourceType||'Capability')}</div>${isNew?'<span class="cardNewBadge" aria-label="New tool">NEW</span>':''}</div><h4>${f.icon} ${esc(f.title)}</h4><p>${esc(f.summary)}</p><button class="btn secondary" data-feature="${f.id}">${f.resourceType==='Agent'?'Open agent guide':'View guidance'}</button></div>`}).join('')}</div></section><section class="panel"><h3>Ready-to-use workflows</h3><p class="sectionIntro">These are practical starting points. Open one to see when to use it, what information you need, and the full prompt.</p><div class="grid">${TOOLS.map(t=>`<div class="card resourceCard"><div class="resourceType">Workflow</div><h4>${t.icon||'🧰'} ${esc(t.title)}</h4><p>${esc(t.summary||t.description)}</p><div class="cardActions"><button class="btn secondary" data-tool-detail="${t.id}">View workflow</button><button class="btn secondary" data-pin-tool="${esc(t.title)}">📌 Pin</button></div></div>`).join('')}</div></section>`}
  function featureDetail(){const f=featureMap[s.activeFeature]||FEATURES[0];if(f.resourceType==='Agent'&&f.methods)return rentHistoryAgentDetail(f);const setup=(f.setup&&f.setup.length)?`<section class="panel"><h3>How to set it up</h3><div class="grid2">${f.setup.map(x=>`<div class="card"><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div>`).join('')}</div></section>`:'';const apps=(f.apps&&f.apps.length)?`<section class="panel"><h3>Vanilla-relevant apps</h3><div class="grid">${f.apps.map(x=>`<div class="card"><h4>${esc(x.name)}</h4><p><strong>${esc(x.status)}</strong></p><p>${esc(x.examples)}</p></div>`).join('')}</div></section>`:'';const troubleshooting=(f.troubleshooting&&f.troubleshooting.length)?`<section class="panel"><h3>Troubleshooting</h3><ul>${f.troubleshooting.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section>`:'';const teamTip=f.teamTip?`<section class="panel teamTip"><div class="eyebrow">Team example</div><h3>${esc(f.teamTip.title||'Team tip')}</h3><p>${esc(f.teamTip.text||'')}</p></section>`:'';const notice=f.notice?`<section class="panel accessNotice"><div class="eyebrow">Temporary access notice</div><p><strong>${esc(f.notice)}</strong></p></section>`:'';return `<div class="breadcrumb"><button class="btn secondary" data-view="resources">Tools & Workflows</button> › ${esc(f.title)}</div><section class="panel hero"><div class="eyebrow">AI capability</div><h2>${f.icon} ${esc(f.title)}</h2><p>${esc(f.summary)}</p><button class="btn secondary" data-pin-tool="${esc(f.title)}">📌 Pin</button></section>${notice}<section class="panel"><h3>Why it matters</h3><p>${esc(f.why)}</p><div class="grid2"><div class="card"><h4>Good uses</h4><ul>${(f.use||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h4>Avoid / watch out</h4><ul>${(f.avoid||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></section>${teamTip}${setup}${apps}${troubleshooting}${f.id==='feature_prompt_builder'?promptBuilderPanel():''}<section class="panel"><h3>Prompt examples</h3>${(f.prompts||[]).map(p=>promptCard(p.title,p.text)).join('')}</section>`}
  function rentHistoryAgentDetail(f){
    const methodCards=(f.methods||[]).map(m=>`<article class="agentMethodCard"><div class="agentMethodTop"><span class="agentMethodNo">${esc(m.number)}</span><div><div class="resourceType">Method ${esc(m.number)}</div><h3>${esc(m.title)}</h3><p>${esc(m.short)}</p></div></div><ol>${(m.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${m.prompt?`<div class="agentPrompt"><div class="agentPromptHead"><strong>Prompt to use</strong><button class="btn secondary" data-copy="${enc(m.prompt)}">Copy prompt</button></div><pre>${esc(m.prompt)}</pre></div>`:`<div class="agentNoPrompt"><strong>No prompt needed.</strong> Upload the CMA PDF and let the agent identify the subject property.</div>`}<div class="agentExpected"><strong>Expected result</strong><ul>${(m.expected||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></article>`).join('');
    return `<div class="breadcrumb"><button class="btn secondary" data-view="resources">Tools & Workflows</button> › ${esc(f.title)}</div>
    <section class="panel hero agentHero"><div class="eyebrow">Vanilla Agent</div><h2>${f.icon} How to Use the ${esc(f.title)}</h2><p>${esc(f.summary)}</p><div class="tools"><span class="pill">Creates branded PDF reports</span><span class="pill">Address or Cotality CMA</span><span class="pill">Single or batch</span><button class="btn secondary" data-pin-tool="${esc(f.title)}">📌 Pin</button></div></section>
    <section class="panel"><h3>What the agent does</h3><p>${esc(f.why)}</p><div class="grid2"><div class="card"><h4>Give it</h4><ul><li>A complete property address</li><li>A Cotality CMA PDF</li><li>Multiple complete addresses or CMA PDFs in one request</li></ul></div><div class="card"><h4>You get</h4><ul><li>A branded Rental Increase History PDF for each property</li><li>Verified rent history matched from the internal spreadsheet</li><li>A rent-growth graph and performance summary</li></ul></div></div></section>
    <section class="panel"><div class="sectionHeading"><div><div class="eyebrow">Choose your method</div><h3>Four ways to use the RentHistory Agent</h3></div></div><p class="sectionIntro">Pick the method that matches what you already have. The agent handles the rent data; your job is to give it the correct property identity and requested output.</p><div class="agentMethodGrid">${methodCards}</div></section>
    <section class="panel agentRules"><div class="grid2"><div><div class="eyebrow">Data rules</div><h3>What the report relies on</h3><ul>${(f.dataRules||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="agentWarning"><div class="eyebrow">Important</div><h3>What not to do</h3><ul>${(f.avoid||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></section>
    <section class="panel"><div class="eyebrow">Expected output</div><h3>What a successful report contains</h3><div class="agentOutputGrid">${(f.outputs||[]).map(x=>`<div class="agentOutputItem">✓ ${esc(x)}</div>`).join('')}</div><div class="callout"><strong>Batch requests stay separate.</strong> Multiple properties are never combined into one report. Successful batch jobs return a separate PDF for each property, normally packaged in a ZIP with a completion summary.</div></section>
    <section class="panel"><div class="eyebrow">Prompt examples</div><h3>Useful ways to ask</h3><p class="promptHint">Use the shortest prompt that clearly identifies the task. Do not add rent figures or ask the agent to estimate missing information.</p>${(f.prompts||[]).map(p=>promptCard(p.title,p.text)).join('')}</section>
    <section class="panel"><div class="eyebrow">Troubleshooting</div><h3>If something does not look right</h3><div class="grid2">${(f.troubleshooting||[]).map(x=>`<div class="card"><h4>${esc(x.title)}</h4><p>${esc(x.text)}</p></div>`).join('')}</div></section>
    <section class="panel escalationPanel"><div class="eyebrow">Escalation</div><h3>Contact Kristie when the data needs review</h3><p>If the rental-history spreadsheet cannot be opened or read, or if someone disputes information shown in a report, contact <strong>Kristie</strong>. Do not ask the agent to invent, estimate or substitute figures.</p></section>
    <section class="panel"><div class="eyebrow">FAQ</div><h3>Common questions</h3><div class="faqAcademy">${(f.faq||[]).map(x=>`<details><summary>${esc(x.q)}</summary><p>${esc(x.a)}</p></details>`).join('')}</div></section>`;
  }

  function toolDetail(){const t=toolMap[s.activeTool]||TOOLS[0];return `<div class="breadcrumb"><button class="btn secondary" data-view="resources">Tools & Workflows</button> › ${esc(t.title)}</div><section class="panel hero"><div class="eyebrow">Ready-to-use workflow</div><h2>${t.icon||'🧰'} ${esc(t.title)}</h2><p>${esc(t.summary||t.description)}</p><div class="cardActions"><button class="btn secondary" data-pin-tool="${esc(t.title)}">📌 Pin</button></div></section><section class="panel"><div class="grid2"><div class="card"><h3>Use this when</h3><ul>${(t.when||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h3>Have this ready</h3><ul>${(t.needs||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></section><section class="panel"><h3>How it works</h3><ol>${(t.steps||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>${t.id==='prompt-builder'?promptBuilderPanel():`<section class="panel"><h3>Workflow prompt</h3><p>Review the prompt below, replace the bracketed fields, then copy it into ChatGPT.</p><div class="promptPreview"><pre>${esc(t.prompt)}</pre></div><button class="btn gold" data-copy="${enc(t.prompt)}">Copy full prompt</button></section>`}`}
  function progress(){return `<section class="panel hero"><div class="eyebrow">Progress</div><h2>My progress</h2><p>Your local view of learning history. Google Sheet stores meaningful events when syncing is enabled.</p></section><section class="panel"><h3>Learning path progress</h3>${PATHS.map(p=>`<div class="tick"><b>${p.icon} ${esc(p.title)}</b><div class="progressbar"><div class="progressfill" style="width:${pctPath(p.id)}%"></div></div>${pctPath(p.id)}%</div>`).join('')}</section><section class="panel"><h3>Journey log</h3>${s.journey.map(j=>`<div class="tick"><b>${esc(j.ts)}</b> — ${esc(j.type)}: ${esc(j.name)} ${j.course?`(${esc(j.course)})`:''}</div>`).join('')||'<p>No activity yet.</p>'}</section><section class="panel"><h3>Confidence</h3>${Object.entries(s.confidence).map(([k,v])=>`<div class="tick">${esc(k)}: <b>${esc(v)}</b></div>`).join('')||'<p>No confidence entries yet.</p>'}</section>`}
  function settings(){const eligible=s.profile.permission==='Administrator'||s.profile.permission==='Trainer';const unlocked=eligible&&s.adminUnlocked;return `<section class="panel hero"><div class="eyebrow">Settings</div><h2>Profile & access</h2></section><section class="panel"><div class="formGrid"><div><label>Name</label><input id="name" value="${esc(s.profile.name)}"></div><div><label>Email</label><input id="email" value="${esc(s.profile.email)}"></div><div><label>Learning role</label><select id="role">${['Business Development Manager','Property Manager','Assistant Property Manager','Administration','Operations','Management','AI Specialist'].map(r=>`<option ${s.profile.role===r?'selected':''}>${r}</option>`).join('')}</select></div><div><label>Current access</label><input value="${esc(s.profile.permission||'Learner')}" disabled></div></div><div class="tools"><button class="btn gold" id="saveProfile">Save profile</button><button class="btn secondary" id="exportData">Export backup</button><button class="btn secondary" id="importData">Import backup</button><button class="btn red" id="resetLocal">Reset local progress</button></div></section>${eligible?`<section class="panel"><h3>Secured administration</h3>${unlocked?`<p>Maintenance controls are available in this secured area and are not shown in the main menu.</p><div class="tools"><button class="btn secondary" data-admin-action="purge_lesson_opened">Purge noisy lesson_opened events</button><button class="btn secondary" data-admin-action="rebuild_summary">Rebuild summaries</button><button class="btn secondary" data-admin-action="remove_duplicates">Remove duplicates</button><button class="btn secondary" id="removeAdmin">Lock administration</button></div>`:`<p>Enter the administrator PIN to reveal maintenance controls.</p><input id="adminPin" placeholder="Administrator PIN"><div class="tools"><button class="btn secondary" id="unlockAdmin">Unlock administration</button></div>`}</section>`:`<section class="panel"><h3>Administrator access</h3><p>This email is currently a Learner. If you should have admin access, add your email to the Permissions tab and save your profile again.</p></section>`}`}


  function promptBuilderPanel(){return `<section class="panel builderPanel"><div class="sectionHeading"><div><div class="eyebrow">Interactive workspace</div><h3>Build a prompt that fits the real task</h3><p>Complete the fields that matter. The builder turns them into a clear prompt you can review, edit and copy.</p></div><button class="btn secondary" id="loadPromptExample">Load example</button></div><div class="builderGrid"><div class="builderFields"><label>What do you need ChatGPT to do?<textarea id="pbTask" rows="3" placeholder="Example: Turn rough client meeting notes into an owner follow-up email and internal action list."></textarea></label><label>Who is using the result, and who is the audience?<input id="pbAudience" placeholder="Example: Property Manager; owner is the external audience"></label><label>Context and facts ChatGPT needs<textarea id="pbContext" rows="4" placeholder="Paste the situation, dates, decisions, property details and relevant background."></textarea></label><label>Required inputs or source material<textarea id="pbInputs" rows="3" placeholder="Example: meeting notes, email thread, quote, lease date"></textarea></label><div class="formGrid"><label>Tone<input id="pbTone" placeholder="Example: calm, confident and concise"></label><label>Output format<input id="pbFormat" placeholder="Example: soft headings + action table"></label></div><label>Rules and boundaries<textarea id="pbRules" rows="3" placeholder="Example: preserve facts; do not invent dates, promises or legal conclusions"></textarea></label><label>What should ChatGPT do when information is missing?<input id="pbClarify" placeholder="Example: ask up to 4 targeted questions before drafting"></label><div class="cardActions"><button class="btn gold" id="buildPrompt">Build prompt</button><button class="btn secondary" id="clearPromptBuilder">Clear</button></div></div><div class="builderOutput"><div class="builderOutputHead"><strong>Your prompt</strong><span class="small" id="pbStatus">Complete the fields, then build.</span></div><div class="promptPreview"><pre id="promptBuilderOutput">Your generated prompt will appear here.</pre></div><button class="btn green" id="copyBuiltPrompt" disabled>Copy built prompt</button><p class="small">Review it before use. A good prompt should make the task clearer without becoming longer than the work itself.</p></div></div></section>`}
  function value(id){const el=document.getElementById(id);return el?el.value.trim():''}
  function buildInteractivePrompt(){const task=value('pbTask');if(!task){toast('Add the task first');document.getElementById('pbTask')?.focus();return}const audience=value('pbAudience'),context=value('pbContext'),inputs=value('pbInputs'),tone=value('pbTone'),format=value('pbFormat'),rules=value('pbRules'),clarify=value('pbClarify');const parts=[`You are helping with this task:\n${task}`];if(audience)parts.push(`User and audience:\n${audience}`);if(context)parts.push(`Context and verified facts:\n${context}`);if(inputs)parts.push(`Source material or inputs to use:\n${inputs}`);if(tone)parts.push(`Tone:\n${tone}`);if(format)parts.push(`Required output:\n${format}`);if(rules)parts.push(`Rules and boundaries:\n${rules}`);parts.push(`Working method:\n1. Separate supplied facts from assumptions.\n2. Identify anything unclear, inconsistent or missing.\n3. Complete the task using only the available evidence.\n4. Check the final result against the requested audience, tone and format.`);parts.push(`Clarification behaviour:\n${clarify||'Ask concise, targeted questions before drafting whenever missing information could materially change the result.'}`);parts.push(`Final quality check:\nBefore answering, confirm that dates, names, amounts, decisions and commitments have not been invented or altered.`);const out=parts.join('\n\n');const pre=document.getElementById('promptBuilderOutput'),btn=document.getElementById('copyBuiltPrompt'),status=document.getElementById('pbStatus');if(pre)pre.textContent=out;if(btn){btn.disabled=false;btn.dataset.builtPrompt=enc(out)}if(status)status.textContent='Ready to review and copy.'}
  function loadPromptExample(){const data={pbTask:'Turn rough notes from a client meeting into a concise owner follow-up email and an internal action register for the Assistant PM.',pbAudience:'The Property Manager will use the result. The email is for the property owner; the action register is for the PM and Assistant PM.',pbContext:'The owner raised concerns about maintenance delays, asked for an updated rent review recommendation and agreed that the smoke alarm quote can proceed up to $180. Follow-up is due tomorrow.',pbInputs:'Voice-dictated meeting notes saved inside the shared ChatGPT Project, the current maintenance timeline and the verified quote.',pbTone:'Professional, calm, accountable and practical.',pbFormat:'Part 1: owner email with soft headings. Part 2: action table with owner, deadline and status.',pbRules:'Do not invent dates, costs, approvals or promises. Keep the owner email under 220 words. Mark unclear items as To confirm.',pbClarify:'Ask no more than 3 questions, and only where the missing information prevents a reliable draft.'};Object.entries(data).forEach(([id,val])=>{const el=document.getElementById(id);if(el)el.value=val});buildInteractivePrompt()}
  function clearPromptBuilder(){['pbTask','pbAudience','pbContext','pbInputs','pbTone','pbFormat','pbRules','pbClarify'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='' });const pre=document.getElementById('promptBuilderOutput'),btn=document.getElementById('copyBuiltPrompt'),status=document.getElementById('pbStatus');if(pre)pre.textContent='Your generated prompt will appear here.';if(btn){btn.disabled=true;delete btn.dataset.builtPrompt}if(status)status.textContent='Complete the fields, then build.'}


  function bind(){document.querySelectorAll('[data-open-bulletin]').forEach(b=>b.onclick=()=>openBulletin(b.dataset.openBulletin));document.querySelectorAll('[data-open-guide]').forEach(b=>b.onclick=()=>openGuide(b.dataset.openGuide,b.dataset.openAnnouncement));document.querySelectorAll('[data-ack-announcement]').forEach(b=>b.onclick=()=>acknowledgeAnnouncement(b.dataset.ackAnnouncement));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{s.view=(b.dataset.view==='dashboard'&&requiredAnnouncements().length)?'requiredBulletin':b.dataset.view;save();render();scrollTop()});document.querySelectorAll('[data-open-path]').forEach(b=>b.onclick=()=>{const p=pathMap[b.dataset.openPath];s.activePath=p.id;s.activeLesson=b.dataset.openLesson||firstIncomplete(p);s.view='course';save();render();scrollTop()});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{const menu=document.getElementById('courseMenu'),y=menu?menu.scrollTop:0;s.activeLesson=b.dataset.lesson;save();render();const m=document.getElementById('courseMenu');if(m)m.scrollTop=y;scrollTop()});document.querySelectorAll('[data-feature]').forEach(b=>b.onclick=()=>{s.activeFeature=b.dataset.feature;markToolSeen(s.activeFeature);s.view='featureDetail';save();render();scrollTop()});document.querySelectorAll('[data-tool-detail]').forEach(b=>b.onclick=()=>{s.activeTool=b.dataset.toolDetail;s.view='toolDetail';save();render();scrollTop()});document.querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>copy(dec(b.dataset.copy)));document.querySelectorAll('[data-pin-tool]').forEach(b=>b.onclick=()=>pin(b.dataset.pinTool));document.querySelectorAll('[data-unpin]').forEach(b=>b.onclick=()=>unpin(b.dataset.unpin));document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>toggleComplete(b.dataset.complete));document.querySelectorAll('[data-confidence]').forEach(b=>b.onclick=()=>setConfidence(b.dataset.confidence));document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{const name=b.dataset.tool;if(toolTitleMap[name]){s.activeTool=toolTitleMap[name].id;s.view='toolDetail'}else if(featureTitleMap[name]){s.activeFeature=featureTitleMap[name].id;markToolSeen(s.activeFeature);s.view='featureDetail'}else{s.view='resources'}save();render();scrollTop()});const bp=document.getElementById('buildPrompt');if(bp)bp.onclick=buildInteractivePrompt;const be=document.getElementById('loadPromptExample');if(be)be.onclick=loadPromptExample;const bc=document.getElementById('clearPromptBuilder');if(bc)bc.onclick=clearPromptBuilder;const bcopy=document.getElementById('copyBuiltPrompt');if(bcopy)bcopy.onclick=()=>{if(bcopy.dataset.builtPrompt)copy(dec(bcopy.dataset.builtPrompt))};const sp=document.getElementById('saveProfile');if(sp)sp.onclick=saveProfile;const ex=document.getElementById('exportData');if(ex)ex.onclick=exportData;const im=document.getElementById('importData');if(im)im.onclick=importData;const rs=document.getElementById('resetLocal');if(rs)rs.onclick=resetLocal;const ua=document.getElementById('unlockAdmin');if(ua)ua.onclick=unlockAdmin;const ra=document.getElementById('removeAdmin');if(ra)ra.onclick=()=>{s.adminUnlocked=false;save();render();toast('Admin access removed')};document.querySelectorAll('[data-admin-action]').forEach(b=>b.onclick=()=>adminAction(b.dataset.adminAction));bindDragPins();bindGuideTracking();}

  function admin(){s.view='settings';save();return settings()}

  function bindGuideTracking(){const frame=document.getElementById('guideFrame');if(!frame)return;frame.onload=()=>{const announcementId=frame.dataset.announcementId;const guideId=frame.dataset.guideId;if(!announcementId)return;ensureAnnouncementOpened(announcementId,guideId);let win,doc;try{win=frame.contentWindow;doc=frame.contentDocument||win.document}catch(e){return}if(!win||!doc)return;let ticking=false;const update=()=>{ticking=false;const root=doc.documentElement,body=doc.body;const top=win.scrollY||root.scrollTop||body.scrollTop||0;const height=Math.max(root.scrollHeight,body.scrollHeight)-win.innerHeight;const pct=height<=0?100:Math.max(0,Math.min(100,Math.round(top/height*100)));recordAnnouncementProgress(announcementId,guideId,pct)};win.addEventListener('scroll',()=>{if(!ticking){ticking=true;win.requestAnimationFrame(update)}},{passive:true});update()}}
  function ensureAnnouncementOpened(id,guideId){const a=(U.announcements||[]).find(x=>x.id===id);if(!a)return;const current=s.announcements[id]||{};if(current.openedAt)return;const now=new Date().toISOString();s.announcements[id]={...current,openedAt:now,progress:Number(current.progress||0),lastMilestone:Number(current.lastMilestone||0)};save();log({type:'announcement_opened',course:'Bulletin Board',chapter:'Required reading',lessonId:id,name:'Announcement opened',itemId:id,itemName:a.title,data:{guideId,status:'Opened',progress:Number(current.progress||0),openedAt:now}})}
  function recordAnnouncementProgress(id,guideId,pct){const a=(U.announcements||[]).find(x=>x.id===id);if(!a)return;const current=s.announcements[id]||{};const previous=Math.max(0,Math.min(100,Number(current.progress||0)));const next=Math.max(previous,Math.max(0,Math.min(100,Number(pct||0))));if(next===previous)return;const milestones=[25,50,75,100];const reached=milestones.filter(m=>m>Number(current.lastMilestone||0)&&next>=m).pop()||Number(current.lastMilestone||0);s.announcements[id]={...current,progress:next,lastMilestone:reached,openedAt:current.openedAt||new Date().toISOString()};save();const bar=document.querySelector('.guideProgressLine .progressfill');if(bar)bar.style.width=next+'%';const label=document.querySelector('.guideProgressLine .small');if(label)label.textContent=next+'% read';if(reached>Number(current.lastMilestone||0)){log({type:'announcement_progress',course:'Bulletin Board',chapter:'Required reading',lessonId:id,name:'Reading progress '+reached+'%',itemId:id,itemName:a.title,data:{guideId,status:reached===100?'Read to end':'In progress',progress:reached,openedAt:s.announcements[id].openedAt}})}}
  function openBulletin(id){const a=(U.announcements||[]).find(x=>x.id===id);if(!a){toast('Bulletin unavailable');return}if(isRequiredAnnouncement(a)&&a.destination&&a.destination.type==='guide'){openGuide(a.destination.id,a.id);return}const current=s.announcements[id]||{};if(!current.seenAt){const now=new Date().toISOString();s.announcements[id]={...current,seenAt:now};save();journey('Bulletin seen',a.title,'Bulletin Board');log({type:'announcement_seen',course:'Bulletin Board',chapter:'Announcement',lessonId:id,name:'Announcement seen',itemId:id,itemName:a.title,data:{status:'Seen',seenAt:now,published:a.published}})}s.activeAnnouncement=id;s.view='announcementDetail';save();render();scrollTop()}
  function openGuide(id,announcementId){if(!GUIDES[id]){toast('Guide unavailable');return;}s.activeGuide=id;s.view='guide';if(announcementId)ensureAnnouncementOpened(announcementId,id);save();render();scrollTop()}
  function acknowledgeAnnouncement(id){if(!s.profile.email){s.view='settings';save();render();toast('Set up your profile first');return}const a=(U.announcements||[]).find(x=>x.id===id);if(!a)return;const now=new Date().toISOString();const current=s.announcements[id]||{};s.announcements[id]={...current,openedAt:current.openedAt||now,progress:100,lastMilestone:100,acknowledgedAt:now};save();journey('Update acknowledged',a.title,'Bulletin Board');log({type:'announcement_acknowledged',course:'Bulletin Board',chapter:'Required reading',lessonId:id,name:'Announcement acknowledged',itemId:id,itemName:a.title,data:{published:a.published,destination:a.destination,status:'Acknowledged',progress:100,openedAt:s.announcements[id].openedAt,acknowledgedAt:now}});s.view=requiredAnnouncements().length?'requiredBulletin':'dashboard';save();render();scrollTop();toast('Acknowledgement recorded')}
  function routePath(){if(location.protocol==='file:'){const h=location.hash.replace(/^#/,'');return h||'/'}return location.pathname||'/'}
  function applyRoute(){
    const path=decodeURIComponent(routePath()).replace(/\/+$/,'')||'/';
    let m;
    if(path==='/'){return false}
    if(path==='/bulletin-board'){s.view='updates';save();return true}
    if((m=path.match(/^\/bulletin-board\/([^/]+)$/))){const a=(U.announcements||[]).find(x=>x.id===m[1]);if(a){if(isRequiredAnnouncement(a)&&a.destination&&a.destination.type==='guide'){s.activeGuide=a.destination.id;s.view='guide'}else{const current=s.announcements[a.id]||{};if(!current.seenAt){const now=new Date().toISOString();s.announcements[a.id]={...current,seenAt:now};journey('Bulletin seen',a.title,'Bulletin Board');log({type:'announcement_seen',course:'Bulletin Board',chapter:'Announcement',lessonId:a.id,name:'Announcement seen',itemId:a.id,itemName:a.title,data:{status:'Seen',seenAt:now,published:a.published}})}s.activeAnnouncement=a.id;s.view='announcementDetail'}save();return true}}
    if(path==='/training'){s.view='learningPaths';save();return true}
    if((m=path.match(/^\/training\/([^/]+)\/([^/]+)$/))&&pathMap[m[1]]&&pathMap[m[1]].lessons[m[2]]){s.activePath=m[1];s.activeLesson=m[2];s.view='course';save();return true}
    if(path==='/tools'){s.view='resources';save();return true}
    if((m=path.match(/^\/agent\/([^/]+)$/))&&featureSlugMap[m[1]]){s.activeFeature=featureSlugMap[m[1]].id;markToolSeen(s.activeFeature);s.view='featureDetail';save();return true}
    if((m=path.match(/^\/tool\/([^/]+)$/))&&featureSlugMap[m[1]]){s.activeFeature=featureSlugMap[m[1]].id;s.view='featureDetail';save();return true}
    if((m=path.match(/^\/workflow\/([^/]+)$/))&&toolSlugMap[m[1]]){s.activeTool=toolSlugMap[m[1]].id;s.view='toolDetail';save();return true}
    if((m=path.match(/^\/guide\/([^/]+)$/))){const g=Object.values(GUIDES).find(x=>(x.slug||x.id)===m[1]);if(g){s.activeGuide=g.id;s.view='guide';save();return true}}
    if(path==='/progress'){s.view='progress';save();return true}
    if(path==='/settings'){s.view='settings';save();return true}
    return false
  }
  function applyStartupView(){if(routePath()!=='/')return;if(requiredAnnouncements().length)s.view='requiredBulletin';else s.view='dashboard';save()}
  function firstIncomplete(p){for(const id of Object.keys(p.lessons)){if(!s.completed[p.id+'__'+id])return id}return Object.keys(p.lessons)[0]}
  function toggleComplete(key){const [pathId,lessonId]=key.split('__');const p=pathMap[pathId], l=p.lessons[lessonId];if(s.completed[key]){delete s.completed[key];journey('Uncompleted',l.title,p.title);log({type:'mission_uncompleted',course:p.title,lessonId:lessonId,name:'Uncompleted '+l.title});toast('Marked incomplete')}else{s.completed[key]=new Date().toISOString();journey('Completed',l.title,p.title);log({type:'mission_completed',course:p.title,lessonId:lessonId,name:'Completed '+l.title});modal(l.title+' complete',l.congrats,'✅');if(pctPath(pathId)===100){journey('Completed path',p.title,p.title);log({type:'path_completed',course:p.title,itemId:pathId+'_certificate',itemName:p.certificate,certificateId:pathId+'_certificate',certificateName:p.certificate,name:p.title+' completed'});setTimeout(()=>modal(p.title+' completed',`Excellent work. You completed ${p.title}. Your progress and certificate event have been recorded.`, '🏆'),700)}}save();render();}
  function setConfidence(val){const p=pathMap[s.activePath],l=p.lessons[s.activeLesson];s.confidence[p.title+' / '+l.title]=val;journey('Confidence',val,p.title+' / '+l.title);log({type:'confidence_selected',course:p.title,lessonId:l.id,name:'Confidence: '+val},{confidence:val});save();toast('Confidence saved')}
  function pin(tool){if(!s.pins.includes(tool))s.pins.push(tool);journey('Pinned',tool);log({type:'tool_pinned',course:'Tools & Workflows',itemName:tool,name:'Pinned '+tool});save();render();toast('Pinned')}
  function unpin(tool){s.pins=s.pins.filter(p=>p!==tool);journey('Unpinned',tool);log({type:'tool_unpinned',course:'Tools & Workflows',itemName:tool,name:'Unpinned '+tool});save();render()}
  function bindDragPins(){const list=document.getElementById('pinList');if(!list)return;let drag=null;list.querySelectorAll('.pin').forEach(el=>{el.ondragstart=()=>{drag=el;el.classList.add('dragging')};el.ondragend=()=>{el.classList.remove('dragging');s.pins=[...list.querySelectorAll('.pin')].map(e=>e.querySelector('span').textContent);save()};el.ondragover=e=>{e.preventDefault();if(drag&&drag!==el){const r=el.getBoundingClientRect();(e.clientY>r.top+r.height/2)?el.after(drag):el.before(drag)}}})}
  function saveProfile(){s.profile.name=document.getElementById('name').value.trim();s.profile.email=document.getElementById('email').value.trim().toLowerCase();s.profile.role=document.getElementById('role').value;save();log({type:'profile_saved',course:'Profile',name:'Profile saved'});AcademySync.jsonp('permission',{email:s.profile.email}).then(r=>{if(r&&r.permission){s.profile.permission=r.permission;save();render();toast('Profile saved: '+r.permission)}else{render();toast('Profile saved')}})}
  function unlockAdmin(){const pin=document.getElementById('adminPin').value.trim();AcademySync.jsonp('checkAdmin',{email:s.profile.email,pin}).then(r=>{if(r&&r.ok){s.adminUnlocked=true;s.profile.permission=r.permission||s.profile.permission;save();render();toast('Administration unlocked in Settings')}else toast((r&&r.error)||'Access denied')})}
  function adminAction(action){const pin=prompt('Administrator PIN');if(!pin)return;AcademySync.jsonp('adminAction',{email:s.profile.email,pin,adminAction:action}).then(r=>toast(r&&r.ok?'Admin action completed':'Admin action failed'))}
  function exportData(){const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='v-academy-backup.json';a.click();log({type:'backup_exported',course:'Settings',name:'Backup exported'})}
  function importData(){const i=document.createElement('input');i.type='file';i.accept='application/json';i.onchange=()=>{const f=i.files[0];const r=new FileReader();r.onload=()=>{try{s={...defaultState,...JSON.parse(r.result)};save();render();toast('Backup imported');log({type:'backup_imported',course:'Settings',name:'Backup imported'})}catch(e){toast('Invalid backup')}};r.readAsText(f)};i.click()}
  function resetLocal(){if(confirm('Reset local progress on this browser? Google Sheet history is not deleted.')){s={...defaultState,profile:s.profile};save();render();toast('Local progress reset');log({type:'reset_progress',course:'Settings',name:'Local reset'})}}
  function scrollTop(){setTimeout(()=>{const m=document.querySelector('.main');if(m)m.scrollTo({top:0,behavior:'smooth'});window.scrollTo({top:0,behavior:'smooth'})},0)}
  return {render,closeModal,applyRoute,applyStartupView};
})();
document.addEventListener('DOMContentLoaded',()=>{const routed=A.applyRoute();if(!routed)A.applyStartupView();A.render()});
window.addEventListener('popstate',()=>{A.applyRoute();A.render()});
